html=r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f7f5f0"><title>Everyday — Personal Dashboard</title>
<style>
:root{--bg:#f7f5f0;--paper:#fffefa;--ink:#20231f;--muted:#777c72;--line:#e8e5dd;--green:#456b54;--green2:#e7efe7;--orange:#c67b48;--lav:#eeebf6;--shadow:0 8px 30px #282d2410;--radius:18px}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}button,input,select,textarea{font:inherit}button{cursor:pointer}.shell{display:grid;grid-template-columns:245px 1fr;min-height:100vh}.side{background:#f0eee8;border-right:1px solid var(--line);padding:26px 16px;position:sticky;top:0;height:100vh;overflow:auto}.brand{display:flex;gap:12px;align-items:center;margin:0 8px 28px}.mark{height:38px;width:38px;border-radius:13px;background:var(--green);color:white;display:grid;place-items:center;font-weight:800;font-size:18px}.brand b{font-size:17px;letter-spacing:-.03em}.brand small{display:block;color:var(--muted);font-size:11px}.navlabel{font-size:10px;text-transform:uppercase;letter-spacing:.12em;color:#96988f;margin:21px 10px 8px}.nav{display:grid;gap:3px}.nav button{border:0;background:transparent;text-align:left;color:#555b52;border-radius:11px;padding:10px 11px;display:flex;gap:11px;align-items:center}.nav button:hover,.nav button.active{background:#fffefa;color:var(--green);font-weight:650}.nav .ico{width:20px;text-align:center;font-size:16px}.sidefoot{margin:25px 7px 0;color:var(--muted);font-size:11px}.main{padding:33px clamp(20px,4vw,58px) 60px;max-width:1480px;width:100%;margin:auto}.top{display:flex;justify-content:space-between;gap:18px;align-items:center;margin-bottom:26px}.eyebrow{color:var(--green);text-transform:uppercase;font-size:10px;letter-spacing:.16em;font-weight:700}.title{font-size:30px;line-height:1.15;letter-spacing:-.045em;margin:4px 0}.subtitle{color:var(--muted);margin:6px 0 0}.topactions{display:flex;gap:8px}.btn{border:1px solid var(--line);background:var(--paper);padding:9px 13px;border-radius:11px;color:var(--ink);font-weight:600}.btn:hover{border-color:#b9c7b8}.btn.primary{background:var(--green);color:white;border-color:var(--green)}.btn.soft{background:var(--green2);border-color:transparent;color:var(--green)}.btn.danger{color:#a24b40}.grid{display:grid;gap:16px}.stats{grid-template-columns:repeat(4,minmax(0,1fr));margin:19px 0 22px}.card{background:var(--paper);border:1px solid var(--line);border-radius:var(--radius);padding:19px;box-shadow:var(--shadow)}.statlabel{color:var(--muted);font-size:12px}.statval{font-size:28px;font-weight:700;letter-spacing:-.04em;margin-top:6px}.statnote{font-size:11px;color:var(--muted);margin-top:4px}.two{grid-template-columns:1.35fr 1fr}.three{grid-template-columns:repeat(3,1fr)}.cardhead{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:12px}.card h2{font-size:16px;letter-spacing:-.02em;margin:0}.card h3{font-size:14px;margin:0 0 5px}.muted{color:var(--muted)}.list{display:grid;gap:9px}.listrow{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:9px 0;border-bottom:1px solid var(--line)}.listrow:last-child{border-bottom:0}.pill{display:inline-block;border-radius:999px;background:#f0eee8;padding:3px 9px;font-size:11px;color:#62665e;white-space:nowrap}.pill.green{background:var(--green2);color:#456b54}.pill.orange{background:#f8eee4;color:#a26535}.quick{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.quick button{border:1px solid var(--line);background:white;border-radius:12px;padding:13px;text-align:left}.quick button:hover{background:var(--green2)}.quick b{display:block;font-size:13px}.quick span{color:var(--muted);font-size:11px}.toolbar{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin:14px 0}.search{min-width:190px;flex:1}.field,select,textarea{border:1px solid var(--line);border-radius:10px;padding:9px 11px;background:#fffefa;color:var(--ink)}.field:focus,select:focus,textarea:focus{outline:2px solid #b7c9b6;border-color:transparent}.tablewrap{overflow:auto;border:1px solid var(--line);border-radius:13px;background:var(--paper)}table{border-collapse:collapse;width:100%;min-width:700px}th,td{padding:11px 12px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top;font-size:13px}th{font-size:10px;text-transform:uppercase;letter-spacing:.09em;color:#858980;background:#f7f6f1;position:sticky;top:0}tr:last-child td{border-bottom:0}td select{padding:6px 8px;font-size:12px;max-width:150px}.rowname{font-weight:650;min-width:210px}.smallbtn{border:0;background:transparent;color:#858980;padding:4px 7px;border-radius:7px}.smallbtn:hover{background:#f2e8e5;color:#a24b40}.empty{padding:32px;text-align:center;color:var(--muted)}.sectionintro{margin-bottom:14px}.sectionintro p{color:var(--muted);margin:4px 0}.routine{display:grid;grid-template-columns:120px 1fr;gap:14px;padding:11px 0;border-bottom:1px solid var(--line)}.routine:last-child{border:0}.routine strong{color:var(--green)}.checkline{display:flex;gap:10px;align-items:flex-start;padding:9px 0;border-bottom:1px solid var(--line)}.checkline:last-child{border:0}.checkline input{accent-color:var(--green);margin-top:5px}.checkline.done span{text-decoration:line-through;color:#96988f}.progress{height:7px;background:#ecebe5;border-radius:9px;overflow:hidden;margin-top:7px}.progress i{display:block;height:100%;background:var(--green);border-radius:9px}.trackergrid{grid-template-columns:1fr 1fr}.itemcontrols{display:flex;gap:5px;align-items:center}.itemcontrols input{width:70px;padding:5px 7px;border:1px solid var(--line);border-radius:8px}.notice{background:#eff3ec;border:1px solid #dce7d9;border-radius:13px;padding:13px 15px;color:#465b47;font-size:13px;margin:16px 0}.modal{position:fixed;inset:0;background:#171b1766;display:grid;place-items:center;padding:20px;z-index:10}.modalbox{background:var(--paper);border-radius:18px;padding:23px;width:min(540px,100%);max-height:90vh;overflow:auto;box-shadow:0 20px 70px #0003}.modalhead{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.formgrid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.formfield{display:grid;gap:5px;font-size:12px;color:var(--muted)}.formfield.full{grid-column:1/-1}.formfield input,.formfield select,.formfield textarea{width:100%}.modalactions{display:flex;justify-content:flex-end;gap:8px;margin-top:17px}.mobilebar{display:none}
@media(max-width:900px){.shell{grid-template-columns:1fr}.side{position:fixed;left:0;right:0;bottom:0;top:auto;width:100%;height:auto;padding:5px 8px calc(5px + env(safe-area-inset-bottom));z-index:5;border:0;border-top:1px solid var(--line);background:#fffefa}.brand,.navlabel,.sidefoot{display:none}.nav{display:flex;justify-content:space-around;gap:0}.nav button{flex:1;justify-content:center;flex-direction:column;gap:1px;padding:5px 1px;font-size:10px}.nav .ico{font-size:16px}.main{padding:22px 16px 95px}.stats{grid-template-columns:repeat(2,1fr)}.two,.trackergrid{grid-template-columns:1fr}.top{align-items:flex-start}.topactions .btn.exportLabel{display:none}.three{grid-template-columns:1fr 1fr}}
@media(max-width:520px){.title{font-size:25px}.topactions .btn{padding:8px 10px;font-size:12px}.stats{gap:9px}.card{padding:15px}.statval{font-size:24px}.quick{grid-template-columns:1fr 1fr}.formgrid{grid-template-columns:1fr}.formfield.full{grid-column:auto}.three{grid-template-columns:1fr 1fr}}
</style></head><body><div class="shell"><aside class="side"><div class="brand"><div class="mark">E</div><div><b>everyday</b><small>your personal dashboard</small></div></div><div class="navlabel">Your space</div><nav class="nav" id="nav"></nav><div class="sidefoot">Private to this browser · Autosaves as you go</div></aside><main class="main"><header class="top"><div><div class="eyebrow">PERSONAL HQ</div><h1 class="title" id="pagetitle">Overview</h1><p class="subtitle" id="pagesub">A calmer place to keep life in view.</p></div><div class="topactions"><button class="btn exportLabel" onclick="exportBackup()">Export backup</button><button class="btn" onclick="document.getElementById('restorefile').click()">Import</button><input id="restorefile" type="file" accept="application/json" hidden onchange="restoreBackup(event)"></div></header><div id="view"></div></main></div><div id="modalroot"></div>
<script>
const seed=__DATA__;
const navItems=[['home','⌂','Overview'],['wardrobe','◈','Wardrobe'],['grooming','✿','Grooming'],['care','♡','Care routine'],['events','▦','Calendar'],['watchlist','▷','Watchlist'],['reading','▤','Reading'],['tasks','✓','Tasks'],['gym','↗','Gym log'],['weight','◌','Weight']];
const initial={wardrobe:seed.wardrobe.map((x,i)=>({...x,id:'w'+i})),grooming:seed.grooming.map((x,i)=>({...x,id:'g'+i})),events:[],watchlist:[],reading:[],tasks:[],gym:[],weight:[],careChecks:{}};
let state;try{state={...initial,...JSON.parse(localStorage.getItem('everyday-personal-dashboard')||'{}')}}catch{state=initial}
let page='home', searchTerm='',filter='All';
const descriptions={home:'A calmer place to keep life in view.',wardrobe:'Your clothes, shoes, and laundry at a glance.',grooming:'Everyday care, grooming, and fragrance stock.',care:'A gentle nudge for the routines that keep things fresh.',events:'Plan what is coming up and send events to your calendar.',watchlist:'Pick up where you left off.',reading:'Keep your books and reading progress together.',tasks:'A simple list for what needs doing.',gym:'Track sessions, exercises, and working weights.',weight:'Log measurements and watch your trend.'};
function save(){localStorage.setItem('everyday-personal-dashboard',JSON.stringify(state))}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function fmtDate(d){if(!d)return 'No date';let x=new Date(d+'T12:00:00');return x.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}
function setPage(p){page=p;searchTerm='';filter='All';render()}
function render(){document.getElementById('pagetitle').textContent=navItems.find(n=>n[0]===page)?.[2]||'Overview';document.getElementById('pagesub').textContent=descriptions[page];document.getElementById('nav').innerHTML=navItems.map(n=>`<button class="${page===n[0]?'active':''}" onclick="setPage('${n[0]}')"><span class="ico">${n[1]}</span>${n[2]}</button>`).join('');document.getElementById('view').innerHTML=({home:homeView,wardrobe:wardrobeView,grooming:groomingView,care:careView,events:eventsView,watchlist:watchView,reading:readingView,tasks:tasksView,gym:gymView,weight:weightView}[page])();}
function countNote(label,num,note){return `<div class="card"><div class="statlabel">${label}</div><div class="statval">${num}</div><div class="statnote">${note}</div></div>`}
function homeView(){let laundry=state.wardrobe.filter(x=>/wash|laundry/i.test(x['Laundry Status'])).length;let low=state.grooming.filter(x=>/low|out|empty/i.test(x['Stock Level'])).length;let next=state.events.filter(x=>x.date).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,4);let open=state.tasks.filter(x=>!x.done).length;return `<div class="grid stats">${countNote('Clothing pieces',state.wardrobe.length,'in your wardrobe inventory')}${countNote('Grooming items',state.grooming.length,'products, tools, and fragrance')}${countNote('Laundry / care',laundry,'items marked for a wash')}${countNote('Open tasks',open,'things still on your list')}</div><div class="grid two"><section class="card"><div class="cardhead"><h2>Coming up</h2><button class="btn soft" onclick="setPage('events')">Open calendar</button></div>${next.length?`<div class="list">${next.map(e=>`<div class="listrow"><div><b>${esc(e.name)}</b><div class="muted">${fmtDate(e.date)} ${e.time?`· ${esc(e.time)}`:''}</div></div><span class="pill">${esc(e.kind||'Event')}</span></div>`).join('')}</div>`:`<div class="empty">Nothing planned yet. Add an event when something comes up.</div>`}</section><section class="card"><div class="cardhead"><h2>Quick add</h2></div><div class="quick"><button onclick="openForm('tasks')"><b>＋ Task</b><span>Capture a to do</span></button><button onclick="openForm('events')"><b>＋ Event</b><span>Plan a date</span></button><button onclick="openForm('watchlist')"><b>＋ Show</b><span>Save a series</span></button><button onclick="openForm('reading')"><b>＋ Book</b><span>Add a read</span></button><button onclick="openForm('gym')"><b>＋ Workout</b><span>Log training</span></button><button onclick="openForm('weight')"><b>＋ Weigh in</b><span>Log weight</span></button></div></section></div><div class="grid two" style="margin-top:16px"><section class="card"><div class="cardhead"><h2>Pick an outfit</h2><button class="smallbtn" onclick="setPage('wardrobe')">Browse →</button></div><div class="list">${state.wardrobe.filter(x=>/wardrobe|clean|ready/i.test(x['Laundry Status'])).slice(0,4).map(x=>`<div class="listrow"><div><b>${esc(x.Name)}</b><div class="muted">${esc(x.Category)} · ${esc(x['Colour / Details'])}</div></div><span class="pill green">Ready</span></div>`).join('')||'<div class="muted">Update laundry status to see outfit-ready pieces here.</div>'}</div></section><section class="card"><div class="cardhead"><h2>Today’s focus</h2><button class="smallbtn" onclick="setPage('tasks')">Tasks →</button></div>${state.tasks.filter(x=>!x.done).slice(0,4).map(t=>`<label class="checkline"><input type="checkbox" onchange="toggleTask('${t.id}')"><span>${esc(t.name)}</span></label>`).join('')||'<div class="empty">No open tasks. Enjoy the breathing room.</div>'}</section></div><div class="notice">Your dashboard saves changes in this browser. Use <b>Export backup</b> occasionally if you want a portable copy.</div>`}
function filtered(list,props){let q=searchTerm.toLowerCase();return list.filter(x=>(filter==='All'||props.some(p=>String(x[p]||'')===filter))&&(!q||Object.values(x).some(v=>String(v).toLowerCase().includes(q))))}
function toolbar(categories,add,placeholder='Search items'){return `<div class="toolbar"><input class="field search" placeholder="${placeholder}" value="${esc(searchTerm)}" oninput="searchTerm=this.value;render()"><select onchange="filter=this.value;render()">${['All',...categories].map(c=>`<option ${c===filter?'selected':''}>${esc(c)}</option>`).join('')}</select><button class="btn primary" onclick="${add}">＋ Add</button></div>`}
function table(headers,rows){return `<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}" class="empty">Nothing here yet.</td></tr>`}</tbody></table></div>`}
function wardrobeView(){let cats=[...new Set(state.wardrobe.map(x=>x.Category).filter(Boolean))].sort();let arr=filtered(state.wardrobe,['Category']);let rows=arr.map(x=>`<tr><td class="rowname">${esc(x.Name)}</td><td>${esc(x.Category)}</td><td>${esc(x['Colour / Details'])}</td><td><span class="pill">${esc(x['Wash Category'])}</span></td><td><select onchange="updateItem('wardrobe','${x.id}','Laundry Status',this.value)">${['In Wardrobe','Clean','In Wash','To Put Away','Worn'].map(s=>`<option ${x['Laundry Status']===s?'selected':''}>${esc(x['Laundry Status']===s?s:s)}</option>`).join('')}${!['In Wardrobe','Clean','In Wash','To Put Away','Worn'].includes(x['Laundry Status'])?`<option selected>${esc(x['Laundry Status'])}</option>`:''}</select></td><td><button class="smallbtn" onclick="removeItem('wardrobe','${x.id}')">×</button></td></tr>`).join('');return `<div class="sectionintro"><p>${state.wardrobe.length} items imported from your wardrobe spreadsheet. Change the laundry status as you wear and wash things.</p></div>${toolbar(cats,"openForm('wardrobe')",'Search clothes, colour, category')} ${table(['Item','Category','Colour / details','Wash group','Laundry status',''],rows)}`}
function groomingView(){let cats=[...new Set(state.grooming.map(x=>x.Category).filter(Boolean))].sort();let arr=filtered(state.grooming,['Category']);let rows=arr.map(x=>`<tr><td class="rowname">${esc(x.Name)}</td><td>${esc(x.Category)}</td><td>${esc(x.Brand)}</td><td>${esc(x.Routine)||'<span class="muted">—</span>'}</td><td><select onchange="updateItem('grooming','${x.id}','Stock Level',this.value)">${['In stock','Running low','Out',''].map(s=>`<option value="${s}" ${(x['Stock Level']||'')===s?'selected':''}>${s||'Not set'}</option>`).join('')}</select></td><td><button class="smallbtn" onclick="removeItem('grooming','${x.id}')">×</button></td></tr>`).join('');return `<div class="sectionintro"><p>${state.grooming.length} items imported. Stock levels were blank in the source sheet; set them as you check your supplies.</p></div>${toolbar(cats,"openForm('grooming')",'Search products or brands')} ${table(['Item','Category','Brand','Routine / use','Stock level',''],rows)}`}
function careView(){let routine=[['Morning','Cleanse: Simple Purifying Gel Wash','Moisturise: Cien, Nivea, or Bulldog'],['Evening','First cleanse: Garnier Micellar Water','Second cleanse: Simple Purifying Gel Wash','Tone / exfoliate: Medicube Zero Pore Pads','Moisturise: Cien, Nivea, or Bulldog']];let items=['Fitted sheet — white · every 2–3 weeks','Duvet cover and pillowcases — green · every 2–3 weeks','Bath towels — taupe / pink / beige · weekly','Gym towel — beige · after each use','Face towels — 3 purple items · every 3 days'];return `<div class="grid two"><section class="card"><div class="cardhead"><h2>Skincare routine</h2><span class="pill green">From your tracker</span></div>${routine.map(r=>`<div class="routine"><strong>${r[0]}</strong><div>${r.slice(1).map(v=>`<div>${esc(v)}</div>`).join('')}</div></div>`).join('')}</section><section class="card"><div class="cardhead"><h2>Bedding & towels</h2><span class="pill">Care cadence</span></div>${items.map((v,i)=>`<label class="checkline ${state.careChecks[i]?'done':''}"><input type="checkbox" ${state.careChecks[i]?'checked':''} onchange="state.careChecks[${i}]=this.checked;save();render()"><span>${esc(v)}</span></label>`).join('')}<p class="muted" style="font-size:12px;margin-top:12px">These checkboxes are a quick “done” note; tick again to reset.</p></section></div>`}
function eventsView(){let arr=state.events.slice().sort((a,b)=>(a.date||'').localeCompare(b.date||''));let rows=arr.filter(x=>!searchTerm||JSON.stringify(x).toLowerCase().includes(searchTerm.toLowerCase())).map(x=>`<tr><td class="rowname">${esc(x.name)}</td><td>${fmtDate(x.date)}</td><td>${esc(x.time||'—')}</td><td>${esc(x.kind||'Event')}</td><td>${esc(x.location||'—')}</td><td><button class="smallbtn" onclick="removeItem('events','${x.id}')">×</button></td></tr>`).join('');return `<div class="sectionintro"><p>Add dates here, then export an .ics calendar file to import into Apple Calendar or Google Calendar. This standalone page cannot sync calendars in the background.</p></div><div class="toolbar"><input class="field search" placeholder="Search events" value="${esc(searchTerm)}" oninput="searchTerm=this.value;render()"><button class="btn primary" onclick="openForm('events')">＋ Add event</button><button class="btn" onclick="exportCalendar()">Export .ics</button></div>${table(['Event','Date','Time','Type','Location / notes',''],rows)}`}
function watchView(){let arr=filtered(state.watchlist,['status']);let rows=arr.map(x=>`<tr><td class="rowname">${esc(x.name)}</td><td><select onchange="updateItem('watchlist','${x.id}','status',this.value)">${['Up next','Watching','Paused','Finished'].map(s=>`<option ${x.status===s?'selected':''}>${s}</option>`).join('')}</select></td><td><div class="itemcontrols"><span>S</span><input type="number" min="1" value="${x.season||1}" onchange="updateItem('watchlist','${x.id}','season',this.value)"><span>E</span><input type="number" min="0" value="${x.episode||0}" onchange="updateItem('watchlist','${x.id}','episode',this.value)"></div></td><td>${esc(x.service||'—')}</td><td>${esc(x.notes||'')}</td><td><button class="smallbtn" onclick="removeItem('watchlist','${x.id}')">×</button></td></tr>`).join('');return `${toolbar(['Up next','Watching','Paused','Finished'],"openForm('watchlist')",'Search your shows')}${table(['Show','Status','Season / episode','Service','Notes',''],rows)}`}
function readingView(){let arr=filtered(state.reading,['status']);let rows=arr.map(x=>{let pct=x.total?Math.min(100,Math.round(100*(x.current||0)/x.total)):0;return `<tr><td class="rowname">${esc(x.name)}<div class="muted">${esc(x.author||'')}</div><div class="progress"><i style="width:${pct}%"></i></div></td><td><select onchange="updateItem('reading','${x.id}','status',this.value)">${['Want to read','Reading','Paused','Finished'].map(s=>`<option ${x.status===s?'selected':''}>${s}</option>`).join('')}</select></td><td><div class="itemcontrols"><input type="number" min="0" value="${x.current||0}" onchange="updateItem('reading','${x.id}','current',this.value)"><span>/</span><input type="number" min="0" value="${x.total||0}" onchange="updateItem('reading','${x.id}','total',this.value)"></div></td><td>${pct}%</td><td>${esc(x.notes||'')}</td><td><button class="smallbtn" onclick="removeItem('reading','${x.id}')">×</button></td></tr>`}).join('');return `${toolbar(['Want to read','Reading','Paused','Finished'],"openForm('reading')",'Search books or authors')}${table(['Book / author','Status','Current / total pages','Progress','Notes',''],rows)}`}
function tasksView(){let arr=state.tasks.filter(x=>!searchTerm||JSON.stringify(x).toLowerCase().includes(searchTerm.toLowerCase())).sort((a,b)=>(a.due||'').localeCompare(b.due||''));return `<div class="sectionintro"><p>This list is stored on this device. It does not sync with Apple Reminders. For reminders and Siri capture, continue using the Reminders app.</p></div><div class="toolbar"><input class="field search" placeholder="Search tasks" value="${esc(searchTerm)}" oninput="searchTerm=this.value;render()"><button class="btn primary" onclick="openForm('tasks')">＋ Add task</button></div><section class="card">${arr.length?arr.map(x=>`<label class="checkline ${x.done?'done':''}"><input type="checkbox" ${x.done?'checked':''} onchange="toggleTask('${x.id}')"><span style="flex:1"><b>${esc(x.name)}</b>${x.due?` <span class="pill">${fmtDate(x.due)}</span>`:''}<div class="muted">${esc(x.notes||'')}</div></span><button class="smallbtn" onclick="event.preventDefault();removeItem('tasks','${x.id}')">×</button></label>`).join(''):'<div class="empty">Your list is clear. Add a task whenever something comes up.</div>'}</section>`}
function gymView(){let arr=state.gym.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||''));let rows=arr.map(x=>`<tr><td>${fmtDate(x.date)}</td><td class="rowname">${esc(x.exercise||x.session)}</td><td>${esc(x.session||'—')}</td><td>${esc(x.sets||'—')}</td><td>${esc(x.reps||'—')}</td><td>${esc(x.load||'—')} kg</td><td>${esc(x.notes||'')}</td><td><button class="smallbtn" onclick="removeItem('gym','${x.id}')">×</button></td></tr>`).join('');return `<div class="sectionintro"><p>Log one row per exercise. Use the notes for set-by-set details if your loads vary within a session.</p></div>${toolbar([],"openForm('gym')",'Search exercises and notes')}${table(['Date','Exercise','Session','Sets','Reps','Load','Notes',''],rows)}`}
function weightView(){let arr=state.weight.slice().sort((a,b)=>(a.date||'').localeCompare(b.date||''));let vals=arr.map(x=>Number(x.value)).filter(Number.isFinite);let min=vals.length?Math.min(...vals):0,max=vals.length?Math.max(...vals):0;let points=arr.map((x,i)=>{let y=max===min?50:85-(Number(x.value)-min)/(max-min)*65;return `${arr.length<2?50:10+i*(80/(arr.length-1))},${y}`}).join(' ');let rows=arr.slice().reverse().map(x=>`<tr><td>${fmtDate(x.date)}</td><td class="rowname">${esc(x.value)} kg</td><td>${esc(x.note||'')}</td><td><button class="smallbtn" onclick="removeItem('weight','${x.id}')">×</button></td></tr>`).join('');return `<div class="toolbar"><button class="btn primary" onclick="openForm('weight')">＋ Add weigh-in</button></div><div class="grid trackergrid"><section class="card"><div class="cardhead"><h2>Weight trend</h2><span class="pill">kg</span></div>${arr.length?`<svg viewBox="0 0 100 100" preserveAspectRatio="none" style="width:100%;height:180px;overflow:visible"><line x1="5" y1="90" x2="95" y2="90" stroke="#e8e5dd"/><polyline fill="none" stroke="#456b54" stroke-width="1.7" points="${points}"/>${arr.map((x,i)=>{let y=max===min?50:85-(Number(x.value)-min)/(max-min)*65;let xx=arr.length<2?50:10+i*(80/(arr.length-1));return `<circle cx="${xx}" cy="${y}" r="2.3" fill="#456b54"><title>${fmtDate(x.date)}: ${x.value} kg</title></circle>`}).join('')}</svg><div class="muted">${vals.length?`Latest: ${vals[vals.length-1]} kg · Range: ${min}–${max} kg`:''}</div>`:'<div class="empty">Add a weigh-in to start your trend.</div>'}</section><section class="card"><h2 style="margin-bottom:12px">Entries</h2>${table(['Date','Weight','Notes',''],rows)}</section></div>`}
function updateItem(type,id,key,value){let x=state[type].find(x=>x.id===id);if(x){x[key]=(['episode','season','current','total','load','sets','reps'].includes(key)?(value===''?'':Number(value)):value);save();render()}}
function removeItem(type,id){if(!confirm('Remove this item from your dashboard?'))return;state[type]=state[type].filter(x=>x.id!==id);save();render()}
function toggleTask(id){let t=state.tasks.find(x=>x.id===id);if(t)t.done=!t.done;save();render()}
const configs={wardrobe:{title:'Add a clothing item',fields:[['name','Item name','text','required'],['category','Category','text'],['colour','Colour / details','text'],['wash','Wash group','text'],['status','Laundry status','text']]},grooming:{title:'Add a grooming item',fields:[['name','Item name','text','required'],['category','Category','text'],['brand','Brand','text'],['routine','Routine / use','text'],['stock','Stock level','select','',['','In stock','Running low','Out']]]},events:{title:'Add an event',fields:[['name','Event name','text','required'],['date','Date','date','required'],['time','Start time','time'],['kind','Type','text'],['location','Location / notes','text']]},watchlist:{title:'Add a show',fields:[['name','Show title','text','required'],['status','Status','select','',['Up next','Watching','Paused','Finished']],['season','Season','number'],['episode','Episode','number'],['service','Streaming service','text'],['notes','Notes','text']]},reading:{title:'Add a book',fields:[['name','Book title','text','required'],['author','Author','text'],['status','Status','select','',['Want to read','Reading','Paused','Finished']],['current','Current page','number'],['total','Total pages','number'],['notes','Notes','text']]},tasks:{title:'Add a task',fields:[['name','Task','text','required'],['due','Due date','date'],['notes','Notes','text']]},gym:{title:'Log a workout exercise',fields:[['date','Date','date'],['exercise','Exercise','text','required'],['session','Session','text'],['sets','Sets','text'],['reps','Reps','text'],['load','Load (kg)','number'],['notes','Set details / notes','textarea']]},weight:{title:'Log body weight',fields:[['date','Date','date','required'],['value','Weight (kg)','number','required'],['note','Notes','text']]}};
function openForm(type){let c=configs[type];if(!c)return;document.getElementById('modalroot').innerHTML=`<div class="modal" onclick="if(event.target===this)closeForm()"><form class="modalbox" onsubmit="submitForm(event,'${type}')"><div class="modalhead"><h2 style="margin:0">${c.title}</h2><button type="button" class="smallbtn" onclick="closeForm()">✕</button></div><div class="formgrid">${c.fields.map(([key,label,t,req,opts])=>`<label class="formfield ${t==='textarea'?'full':''}">${label}${t==='select'?`<select name="${key}">${opts.map(o=>`<option>${esc(o)}</option>`).join('')}</select>`:t==='textarea'?`<textarea name="${key}" rows="3"></textarea>`:`<input name="${key}" type="${t}" ${req==='required'?'required':''} ${t==='number'?'step="any" min="0"':''}>`}</label>`).join('')}</div><div class="modalactions"><button type="button" class="btn" onclick="closeForm()">Cancel</button><button class="btn primary">Save</button></div></form></div>`}
function closeForm(){document.getElementById('modalroot').innerHTML=''}
function submitForm(e,type){e.preventDefault();let data=Object.fromEntries(new FormData(e.target).entries());let o={id:type+Date.now(),...data};if(type==='wardrobe')o={'id':o.id,Name:o.name,Category:o.category,'Colour / Details':o.colour,'Wash Category':o.wash,'Laundry Status':o.status||'In Wardrobe'};if(type==='grooming')o={'id':o.id,Name:o.name,Category:o.category,Brand:o.brand,Routine:o.routine,'Stock Level':o.stock};if(type==='watchlist'){o.season=Number(o.season)||1;o.episode=Number(o.episode)||0}if(type==='reading'){o.current=Number(o.current)||0;o.total=Number(o.total)||0}if(type==='weight')o.value=Number(o.value);state[type].push(o);save();closeForm();render()}
function exportBackup(){let b=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});download(b,'everyday-dashboard-backup.json')}
function restoreBackup(e){let f=e.target.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{try{let d=JSON.parse(r.result);if(!d.wardrobe||!d.grooming)throw 0;state={...initial,...d};save();render();alert('Backup imported.')}catch{alert('That file is not a valid dashboard backup.')}};r.readAsText(f);e.target.value=''}
function download(b,name){let a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function icsEscape(s){return String(s||'').replace(/\\/g,'\\\\').replace(/,/g,'\\,').replace(/;/g,'\\;').replace(/\n/g,'\\n')}
function exportCalendar(){if(!state.events.length){alert('Add an event first.');return}let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Everyday Personal Dashboard//EN'];for(let e of state.events){if(!e.date)continue;let date=e.date.replaceAll('-','');let time=(e.time||'09:00').replace(':','')+'00';lines.push('BEGIN:VEVENT',`UID:${e.id}@everyday-dashboard`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}`,`DTSTART:${date}T${time}`,`SUMMARY:${icsEscape(e.name)}`,`DESCRIPTION:${icsEscape([e.kind,e.location].filter(Boolean).join(' · '))}`,'END:VEVENT')}lines.push('END:VCALENDAR');download(new Blob([lines.join('\r\n')],{type:'text/calendar'}),'everyday-events.ics')}
render();
</script></body></html>'''.replace('__DATA__',json.dumps(data,ensure_ascii=False,separators=(',',':')))
out=root/'outputs'/'Everyday Personal Dashboard.html'
out.write_text(html,encoding='utf-8')
print(out, out.stat().st_size)
